$('#timeUnit').onchange=e=>{timeUnit=e.target.value;syncTimeUnitUI();render()};$('#chronologicalTextSize').oninput=e=>{chronologicalTextSize=Math.max(6,Math.min(32,Number(e.target.value)||9));render()};$('#showAllTimeCounts').onchange=e=>{showAllTimeCounts=e.target.checked;render()};function applyTheme(theme){$('#themeSelect').value=theme;document.body.classList.toggle('dark',theme==='dark');document.body.classList.toggle('print-bw',theme==='print-bw');$('#customThemeControls').hidden=theme!=='custom';customTheme={...defaultCustomTheme,...customTheme};Object.entries(customTheme).forEach(([key,value])=>{const input=$(`#custom${key[0].toUpperCase()+key.slice(1)}`);if(input)input.value=value});const root=document.documentElement,vars=['bg','panel','ink','muted','line','grid','accent'];vars.forEach(key=>root.style.removeProperty(`--${key}`));const palette=theme==='custom'?customTheme:theme==='print-bw'?printTheme:null;if(palette)vars.forEach(key=>root.style.setProperty(`--${key}`,palette[key]));schedulePersist()}$('#themeSelect').onchange=e=>applyTheme(e.target.value);$('#themeToggle').onclick=()=>applyTheme(document.body.classList.contains('dark')?'light':'dark');['Bg','Panel','Ink','Muted','Line','Grid','Accent'].forEach(key=>{$(`#custom${key}`).oninput=e=>{customTheme[key.toLowerCase()]=e.target.value;applyTheme('custom')}});$('#gridToggle').onchange=e=>world.classList.toggle('no-grid',!e.target.checked);
$('#eventSearch').oninput=e=>{eventSearch=e.target.value;render()};$('#eventSearchClear').onclick=()=>{eventSearch='';$('#eventSearch').value='';render();$('#eventSearch').focus()};
function toggleLayer(button,name){const off=button.classList.toggle('off');document.body.classList.toggle(`hide-${name}`,off);button.querySelector('.eye').textContent=off?'○':'◉';schedulePersist()}
$('#eventsLayer').onclick=()=>toggleLayer($('#eventsLayer'),'events');$('#notesLayer').onclick=()=>toggleLayer($('#notesLayer'),'notes');$('#gridLayer').onclick=()=>{const off=$('#gridLayer').classList.toggle('off');world.classList.toggle('no-grid',off);$('#gridLayer .eye').textContent=off?'○':'◉';$('#gridToggle').checked=!off};
$('#structureTemplate').onchange=e=>{const template=e.target.value;if(template==='none'){if(structure.length)lastCustomStructure=structuredClone(structure);structure=[]}else if(template==='custom'){structure=structuredClone(lastCustomStructure)}else{structure=structureTemplates[template].map(([label,time])=>({label,time,color:customTheme.accent}));lastCustomStructure=structuredClone(structure)}render()};
$('#addStructurePoint').onclick=()=>{const last=structure.at(-1);structure.push({label:'New story beat',time:last?last.time+5:0,color:customTheme.accent});lastCustomStructure=structuredClone(structure);$('#structureTemplate').value='custom';render()};
function positionFloatingMenu(menu,x,y){menu.hidden=false;const width=menu.offsetWidth,height=menu.offsetHeight;menu.style.left=`${Math.max(8,Math.min(x,window.innerWidth-width-8))}px`;menu.style.top=`${Math.max(8,Math.min(y,window.innerHeight-height-8))}px`}function currentInkColor(){return getComputedStyle(document.body).getPropertyValue('--ink').trim()||'#252724'}
function openNoteMenu(index,x,y){const note=notes[index],menu=$('#noteMenu');editingNote=index;$('#noteTextInput').value=note.text;$('#noteColorInput').value=note.color||'#545750';$('#noteSizeInput').value=note.size||12;$('#noteBoldInput').checked=!!note.bold;$('#noteItalicInput').checked=!!note.italic;positionFloatingMenu(menu,x,y)}function closeNoteMenu(){$('#noteMenu').hidden=true;editingNote=null}$('#noteMenuClose').onclick=closeNoteMenu;$('#noteApply').onclick=()=>{if(editingNote===null)return;const note=notes[editingNote];note.text=$('#noteTextInput').value.trim()||note.text;note.color=$('#noteColorInput').value;note.size=Math.max(8,Math.min(48,Number($('#noteSizeInput').value)));note.bold=$('#noteBoldInput').checked;note.italic=$('#noteItalicInput').checked;closeNoteMenu();render()};$('#noteDelete').onclick=()=>{if(editingNote===null)return;notes.splice(editingNote,1);closeNoteMenu();render()};
function openStructureMenu(index,x,y){const point=structure[index],menu=$('#structureMenu');editingStructure=index;$('#structureLabelInput').value=point.label;$('#structureColorInput').value=point.color||customTheme.accent;$('#structureTextColorInput').value=point.textColor||currentInkColor();$('#structureTextSizeInput').value=point.textSize||10;$('#structureBoldInput').checked=!!point.bold;$('#structureItalicInput').checked=!!point.italic;$('#structureTimeInput').value=Number(point.time.toFixed(3));positionFloatingMenu(menu,x,y)}
function closeStructureMenu(){$('#structureMenu').hidden=true;editingStructure=null}
$('#structureMenuClose').onclick=closeStructureMenu;
$('#structurePointApply').onclick=()=>{if(editingStructure===null)return;const point=structure[editingStructure];point.label=$('#structureLabelInput').value.trim()||point.label;point.color=$('#structureColorInput').value;point.textColor=$('#structureTextColorInput').value;point.textSize=Math.max(8,Math.min(36,Number($('#structureTextSizeInput').value)));point.bold=$('#structureBoldInput').checked;point.italic=$('#structureItalicInput').checked;point.time=Number($('#structureTimeInput').value);lastCustomStructure=structuredClone(structure);$('#structureTemplate').value='custom';closeStructureMenu();render()};
$('#structurePointDelete').onclick=()=>{if(editingStructure===null)return;structure.splice(editingStructure,1);lastCustomStructure=structuredClone(structure);$('#structureTemplate').value='custom';closeStructureMenu();render()};
function syncSpreadControl(){const plotOnly=spreadMode==='plot',value=plotOnly?plotStretch:timeStretch;$('#spreadRange').value=value;$('#spreadRange').ariaLabel=plotOnly?'Plot-only horizontal stretch':'Entire project horizontal spread';$('#spreadValue').value=`${Math.round(value*100)}%`;$('#spreadProject').classList.toggle('mode-active',!plotOnly);$('#stretchPlot').classList.toggle('mode-active',plotOnly)}function openSpread(mode){spreadMode=mode;$('#spreadControl').hidden=false;syncSpreadControl();schedulePersist()}$('#spreadProject').onclick=()=>openSpread('all');$('#stretchPlot').onclick=()=>openSpread('plot');$('#spreadRange').onpointerdown=()=>editBaseline=snapshot();$('#spreadRange').oninput=e=>{if(spreadMode==='plot')plotStretch=Number(e.target.value);else timeStretch=Number(e.target.value);syncSpreadControl();render()};$('#spreadRange').ondblclick=()=>{if(spreadMode==='plot')plotStretch=1;else timeStretch=1;syncSpreadControl();render()};
function restoreWithoutViewport(value){const view={panX,panY,scale};restore(value);panX=view.panX;panY=view.panY;scale=view.scale;updateTransform()}
function doUndo(){const previous=history.pop();if(previous){redoStack.push(snapshot());restoreWithoutViewport(previous)}syncHistoryButtons()}
function doRedo(){const next=redoStack.pop();if(next){history.push(snapshot());restoreWithoutViewport(next)}syncHistoryButtons()}
$('#undoButton').onclick=doUndo;$('#topUndo').onclick=doUndo;$('#topRedo').onclick=doRedo;
window.addEventListener('keydown',e=>{const command=e.ctrlKey||e.metaKey,key=e.key.toLowerCase(),typing=['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName);if(command&&key==='z'){e.preventDefault();e.shiftKey?doRedo():doUndo();return}if(command&&key==='s'){e.preventDefault();$('#saveFile').click();return}if(command&&key==='f'){e.preventDefault();$('#eventSearch').focus();$('#eventSearch').select();return}if(typing)return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const amount=e.shiftKey?140:45;if(e.key==='ArrowLeft')panX+=amount;if(e.key==='ArrowRight')panX-=amount;if(e.key==='ArrowUp')panY+=amount;if(e.key==='ArrowDown')panY-=amount;updateTransform();return}if(key==='+'||key==='=')zoomAt(scale+.1);else if(key==='-')zoomAt(scale-.1);else if(key==='f')$('#fitView').click();else if({v:'pan',e:'event',n:'note',m:'marquee',g:'group'}[key]){tool={v:'pan',e:'event',n:'note',m:'marquee',g:'group'}[key];activateTool()}else if(e.key==='Escape'){eventSearch='';$('#eventSearch').value='';selected=null;descriptionOpen=null;selectedPoints.clear();render()}});
document.addEventListener('focusin',e=>{if(e.target.matches('input,select,textarea')&&!e.target.closest('.projects-drawer'))editBaseline=snapshot()});
document.addEventListener('change',e=>{if(editBaseline&&e.target.matches('input,select,textarea')){remember(editBaseline);editBaseline=null;schedulePersist()}});
document.addEventListener('click',e=>{if(e.target.closest('#undoButton,#saveFile,#projectsToggle,#projectsClose,#settingsToggle,#settingsClose,#timelineMenuClose'))return;const action=e.target.closest('#addTimeline,#timelineSave,#timelineDelete,#toggleDiegetic,#deleteEvent,#newProject,#addStructurePoint,.visibility,#eventsLayer,#notesLayer,#gridLayer,#themeToggle,#structurePointApply,#structurePointDelete,#noteApply,#noteDelete,#appearanceApply');if(action)remember()},true);
$('#printHotkeys').onclick=()=>{const popup=window.open('','_blank','width=720,height=800');if(!popup)return alert('Allow pop-ups to print the shortcut list.');popup.document.write(`<!doctype html><title>Storyline keyboard shortcuts</title><style>body{font:16px Arial;padding:40px;color:#111}h1{font-size:24px}dl div{display:grid;grid-template-columns:220px 1fr;padding:10px 0;border-bottom:1px solid #ddd}dt{font-weight:700}dd{margin:0}@media print{body{padding:0}}</style><h1>Storyline keyboard shortcuts</h1>${$('.shortcut-list').outerHTML}`);popup.document.close();popup.focus();popup.print()};
let toolbarDrag=null;$('#toolbarGrip').onpointerdown=e=>{e.preventDefault();remember();const bar=$('.floating-tools'),shell=$('#canvasShell').getBoundingClientRect(),rect=bar.getBoundingClientRect();bar.style.transform='none';bar.style.left=`${rect.left-shell.left}px`;bar.style.top=`${rect.top-shell.top}px`;toolbarDrag={x:e.clientX,y:e.clientY,left:rect.left-shell.left,top:rect.top-shell.top};e.target.setPointerCapture(e.pointerId)};
$('#toolbarGrip').onpointermove=e=>{if(!toolbarDrag)return;const bar=$('.floating-tools'),shell=$('#canvasShell');bar.style.left=`${Math.max(0,Math.min(shell.clientWidth-bar.offsetWidth,toolbarDrag.left+e.clientX-toolbarDrag.x))}px`;bar.style.top=`${Math.max(0,Math.min(shell.clientHeight-bar.offsetHeight,toolbarDrag.top+e.clientY-toolbarDrag.y))}px`};$('#toolbarGrip').onpointerup=()=>{toolbarDrag=null;schedulePersist()};
refreshRecentProjects();window.addEventListener('pagehide',()=>{try{localStorage.setItem(STORAGE_KEY,snapshot())}catch{}});try{const saved=localStorage.getItem(STORAGE_KEY);if(saved)restore(saved);else{renderTimelines();render();updateTransform()}}catch{renderTimelines();render();updateTransform()}syncHistoryButtons();
